package com.gathin.tvhome;
import android.app.*;
import android.content.*;
import android.view.*;
import android.widget.*;
import java.util.*;
/** An optional scene schedule changes backgrounds only, while Home is visible. */
final class SceneSchedules {
    static final String KEY="scene_schedule_v1";
    static SceneSchedulePolicy.Spec read(Context c){try{return SceneSchedulePolicy.parse(ProfileStore.preferences(c).getString(KEY,""));}catch(RuntimeException bad){return SceneSchedulePolicy.parse("");}}
    static String current(Context c){Calendar now=Calendar.getInstance();return read(c).select((now.get(Calendar.DAY_OF_WEEK)+5)%7,now.get(Calendar.HOUR_OF_DAY)*60+now.get(Calendar.MINUTE));}
    static void validate(Context c,Map<String,Object> values){String raw=(String)values.getOrDefault(KEY,ProfileStore.preferences(c).getString(KEY,""));SceneSchedulePolicy.Spec spec=SceneSchedulePolicy.parse(raw);String playlist=(String)values.getOrDefault(WallpaperPlaylistChoice.KEY,ProfileStore.preferences(c).getString(WallpaperPlaylistChoice.KEY,""));spec.validatePlaylist(PlaylistPolicy.parse(playlist).tokens);}
    /** Recovery replaces the whole allowlist: omitted choices are cleared, never inherited. */
    static void validateReplacement(Map<String,Object> values){SceneSchedulePolicy.Spec spec=SceneSchedulePolicy.parse((String)values.getOrDefault(KEY,""));spec.validatePlaylist(PlaylistPolicy.parse((String)values.getOrDefault(WallpaperPlaylistChoice.KEY,"")).tokens);}
    static void show(Activity a){new Editor(a).show();}
    private static final class Editor {
        final Activity a;final String profile;final Map<String,?> initial;final List<SceneSchedulePolicy.Rule> rules;final List<ThemeLibrary.Entry> entries;boolean enabled;LinearLayout rows;AlertDialog dialog;
        Editor(Activity a){this.a=a;profile=ProfileStore.id();initial=ProfileStore.preferences(a).getAll();SceneSchedulePolicy.Spec s=read(a);enabled=s.enabled;rules=new ArrayList<>(s.rules);entries=WallpaperPlaylistChoice.entries(a,WallpaperPlaylistChoice.read(a));}
        TextView row(String label,Runnable action){TextView v=new TextView(a);v.setText(label);v.setTextColor(-1);v.setTextSize(17);v.setPadding(20,16,20,16);v.setMinHeight(Math.round(48*a.getResources().getDisplayMetrics().density));v.setFocusable(true);v.setClickable(true);v.setBackgroundResource(R.drawable.settings_choice_bg);v.setOnClickListener(x->action.run());rows.addView(v);return v;}
        void show(){rows=new LinearLayout(a);rows.setOrientation(LinearLayout.VERTICAL);ScrollView scroll=new ScrollView(a);scroll.addView(rows);dialog=new AlertDialog.Builder(a).setTitle("Scene schedules").setMessage("Local time, only while Home is visible. No wakeups or profile changes. Outside these windows, the normal playlist resumes where it paused.").setView(scroll).setNegativeButton(android.R.string.cancel,null).setPositiveButton("Apply",null).create();refresh();dialog.setOnShowListener(d->{rows.getChildAt(0).requestFocus();dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->save());});dialog.show();}
        void refresh(){rows.removeAllViews();row("Scene schedules · "+(enabled?"On":"Off"),()->{enabled=!enabled;refresh();});for(int i=0;i<rules.size();i++){final int at=i;SceneSchedulePolicy.Rule r=rules.get(i);row(days(r.days)+" · "+time(r.start)+"–"+time(r.end)+" · "+name(r.token),()->new AlertDialog.Builder(a).setTitle(name(r.token)).setItems(new String[]{"Edit window","Remove window"},(d,n)->{if(n==0)edit(at);else{rules.remove(at);refresh();}}).setNegativeButton(android.R.string.cancel,null).show());}row("Add scene window",()->edit(-1));}
        String name(String token){for(ThemeLibrary.Entry e:entries)if(e.token.equals(token))return e.pack.name;return "Unavailable wallpaper";}
        void edit(int at){if(entries.isEmpty()){Toast.makeText(a,"Choose wallpapers in Wallpaper playlist first",Toast.LENGTH_LONG).show();return;}if(at<0&&rules.size()>=8){Toast.makeText(a,"Maximum eight scene windows",Toast.LENGTH_LONG).show();return;}String[] names=new String[entries.size()];for(int i=0;i<names.length;i++)names[i]=entries.get(i).pack.name;new AlertDialog.Builder(a).setTitle("Scene wallpaper").setItems(names,(d,n)->{SceneSchedulePolicy.Rule old=at<0?null:rules.get(at);int mask=old==null?127:old.days;boolean[] checked=new boolean[7];for(int i=0;i<7;i++)checked[i]=(mask&(1<<i))!=0;new AlertDialog.Builder(a).setTitle("Days this window starts").setMultiChoiceItems(new String[]{"Monday","Tuesday","Wednesday","Thursday","Friday","Saturday","Sunday"},checked,(x,i,on)->checked[i]=on).setNegativeButton(android.R.string.cancel,null).setPositiveButton("Next",(x,w)->{int dayMask=0;for(int i=0;i<7;i++)if(checked[i])dayMask|=1<<i;final int days=dayMask;if(days==0){Toast.makeText(a,"Choose at least one day",Toast.LENGTH_LONG).show();return;}int start=old==null?1080:old.start,end=old==null?1380:old.end;TimePickerDialog from=new TimePickerDialog(a,(picker,h,m)->new TimePickerDialog(a,(p,eh,em)->{try{SceneSchedulePolicy.Rule next=new SceneSchedulePolicy.Rule(days,h*60+m,eh*60+em,entries.get(n).token);List<SceneSchedulePolicy.Rule> test=new ArrayList<>(rules);if(at<0)test.add(next);else test.set(at,next);new SceneSchedulePolicy.Spec(false,test);rules.clear();rules.addAll(test);refresh();}catch(Exception invalid){Toast.makeText(a,invalid.getMessage(),Toast.LENGTH_LONG).show();}},end/60,end%60,true).show(),start/60,start%60,true);from.setTitle("Start time");from.show();}).show();}).setNegativeButton(android.R.string.cancel,null).show();}
        void save(){try{if(!LauncherLock.require(a,this::save))return;if(!profile.equals(ProfileStore.id())||!initial.equals(ProfileStore.preferences(a).getAll()))throw new IllegalArgumentException("Home changed. Open scene schedules again.");SceneSchedulePolicy.Spec s=new SceneSchedulePolicy.Spec(enabled,rules);Map<String,Object> values=new HashMap<>();values.put(KEY,s.encode());validate(a,values);if(enabled&&!WallpaperPlaylistChoice.enabled(a))throw new IllegalArgumentException("Turn on Wallpaper playlist before enabling scene schedules");if(s.encode().equals(ProfileStore.preferences(a).getString(KEY,""))){dialog.dismiss();return;}ProductFeatures.beforeChange(a,"Change scene schedules");values.put(Config.SETTINGS_REVISION_KEY,ProfileStore.preferences(a).getLong(Config.SETTINGS_REVISION_KEY,0)+1);if(!SetupValues.commit(ProfileStore.preferences(a),values))throw new IllegalStateException("Could not save scene schedules");dialog.dismiss();a.finish();}catch(Exception invalid){Toast.makeText(a,invalid.getMessage(),Toast.LENGTH_LONG).show();}}
    }
    private static String time(int minute){return String.format(Locale.getDefault(),"%02d:%02d",minute/60,minute%60);}
    private static String days(int mask){if(mask==127)return "Every day";if(mask==31)return "Weekdays";if(mask==96)return "Weekends";String[] names={"Mon","Tue","Wed","Thu","Fri","Sat","Sun"};List<String> chosen=new ArrayList<>();for(int i=0;i<7;i++)if((mask&(1<<i))!=0)chosen.add(names[i]);return String.join(", ",chosen);}
}
